const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([140.878144, 27.245974]);
  const buffer = point.buffer(2000); // 2 km radius
  const date = '2014-03-30';
  const startDate = ee.Date(date).advance(-1, 'month'); // one month before
  const endDate = ee.Date(date).advance(1, 'month');   // one month after

  // Function to mask clouds and shadows for Landsat 8 SR
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    return image.updateMask(qaMask).updateMask(saturationMask);
  }

  // Function to mask clouds for Landsat 7
  function maskL7sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  // 2. Data Acquisition - try Landsat 8 first
  let l8col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterBounds(point)
                .filterDate(startDate, endDate)
                .map(maskL8sr)
                .sort('CLOUD_COVER');

  let l8size = l8col.size().getInfo();
  console.log(`Landsat 8 images found: ${l8size}`);

  let image;
  let collectionUsed = 'L8';
  if (l8size === 0) {
    // Fallback to Landsat 7
    console.log('Trying Landsat 7 as fallback...');
    let l7col = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
                  .filterBounds(point)
                  .filterDate(startDate, endDate)
                  .map(maskL7sr)
                  .sort('CLOUD_COVER');
    let l7size = l7col.size().getInfo();
    console.log(`Landsat 7 images found: ${l7size}`);
    if (l7size === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
    image = ee.Image(l7col.first());
    collectionUsed = 'L7';
  } else {
    image = ee.Image(l8col.first());
  }

  // Get cloud cover property
  let cloudCover = image.get('CLOUD_COVER').getInfo();
  console.log(`Selected image from ${collectionUsed}, Cloud cover (%): ${cloudCover}`);

  // 3. Check valid pixels after cloud masking
  let validMask = image.select('SR_B3').mask(); // using green band to check
  let validCount = validMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  }).get('SR_B3').getInfo();
  console.log(`Valid pixels in buffer: ${validCount}`);

  if (validCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Compute NDWI and land/water mask
  let ndwi;
  if (collectionUsed === 'L8') {
    ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']); // Green, NIR
  } else {
    // Landsat 7: B2 (Green), B4 (NIR)
    ndwi = image.normalizedDifference(['SR_B2', 'SR_B4']);
  }
  // Water where NDWI > 0.1
  let waterMask = ndwi.gt(0.1);
  let landMask = waterMask.not();

  // 5. Connected components to find islands
  // Use 4-connected (default) with a max of 256 labels (enough for small area)
  let conn = landMask.connectedComponents({
    neighborhood: ee.Kernel.square(1),
    maxSize: 256
  });

  // Clip to buffer
  conn = conn.clip(buffer);

  // Get frequency of labels in the buffer
  let histogram = conn.reduceRegion({
    reducer: ee.Reducer.frequencyHistogram(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  }).get('labels').getInfo();

  // Count labels (excluding 0 which is water/background)
  let islandCount = 0;
  if (histogram) {
    // histogram is an object with keys as label strings
    for (let key in histogram) {
      if (key !== '0') {
        islandCount++;
      }
    }
  } else {
    // If histogram is null, then no land pixels? But we checked validCount.
    // Let's check land pixel count directly.
    let landCount = landMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: buffer,
      scale: 30,
      maxPixels: 1e9
    }).get('nd').getInfo(); // band name after not() is 'nd'
    if (landCount === null) {
      console.log('Failed to compute land count.');
      console.log('<answer>C3</answer>');
      return;
    }
    if (landCount > 0) {
      // If there are land pixels but histogram failed, we cannot determine islands.
      console.log('Histogram failed but land exists.');
      console.log('<answer>C3</answer>');
      return;
    }
    // else islandCount remains 0
  }

  console.log(`Number of islands detected: ${islandCount}`);

  // 6. Validation & Final Answer
  if (islandCount === 2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
